/* SYNTHETIC MOCK: illustrative decompiler-style reconstruction; not produced by Ghidra.
 * Recovered symbol hypothesis: score_task_priority(TaskView*, int64_t now_epoch).
 * Behavioral observations encoded for handoff testing:
 * - completed tasks score 0 regardless of due date or importance.
 * - overdue tasks gain 40 points per complete overdue day; partial days add no points, capped at 120.
 * - due now through 24 hours adds 80; later than 24 hours through 7 days adds 35; otherwise adds 0.
 * - negative importance is clamped to 0; importance above 5 is clamped to 5.
 * - score is urgency + 30 * importance, capped at 200.
 */
int urgency_bucket(int64_t due_epoch, int64_t now_epoch) {
    int64_t delta = due_epoch - now_epoch;
    if (delta < 0) {
        int64_t days_late = (-delta) / 86400;
        int points = (int)(days_late * 40);
        return points > 120 ? 120 : points;
    }
    if (delta <= 86400) return 80;
    if (delta <= 604800) return 35;
    return 0;
}

int score_task_priority(TaskView *task, int64_t now_epoch) {
    if (task->completed != 0) return 0;
    int importance = task->importance;
    if (importance < 0) importance = 0;
    if (importance > 5) importance = 5;
    int score = urgency_bucket(task->due_epoch, now_epoch) + 30 * importance;
    return score > 200 ? 200 : score;
}
